import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleClaimInClosedPeriod {
    public void handle(@Parameter ClaimInClosedPeriodException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.UNPROCESSABLE_ENTITY));
    }
}
package net.officefloor.hq.app.claim;

/** A claim dated inside a closed period cannot be added, edited, opened, settled or voided. */
public class ClaimInClosedPeriodException extends Exception {

    public ClaimInClosedPeriodException(String message) {
        super(message);
    }
}
-- A sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(255)  NOT NULL,
    grade    VARCHAR(1)    NOT NULL,
    rate     DECIMAL(9, 2) NOT NULL CHECK (rate >= 0),
    PRIMARY KEY (sheet_id, grade)
);
-- A sheet's periods: a name unique on the sheet and a from and to date, inclusive. No two periods
-- of a sheet overlap (checked when one is added).
CREATE TABLE period (
    sheet_id  VARCHAR(255) NOT NULL,
    name      VARCHAR(255) NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date),
    PRIMARY KEY (sheet_id, name)
);
